#!/bin/bash
# 🗡️ GRIM REAPER - ANIMATED MASTER INSTALLER (OPTIMIZED)
# This is the installer served by get.grim.so
# Downloads and installs the complete Grim system with animated progress
# Generated by modular merge system - DO NOT EDIT MANUALLY
# OPTIMIZED VERSION: Defers heavy operations to post-install for 5000+ users

set -euo pipefail

# ============================================================================
# POST-INSTALL OPTIMIZATION FLAGS
# ============================================================================
DEFER_TO_POST_INSTALL=false
POST_INSTALL_AVAILABLE=false

# Check if post-install.sh will be available
check_post_install_availability() {
    # Check various locations where post-install.sh might be
    if [[ -f "post-install.sh" ]] || [[ -f "${GRIM_INSTALL_DIR:-}/post-install.sh" ]] || [[ -f "${GRIM_GRAVEYARD:-}/post-install.sh" ]]; then
        POST_INSTALL_AVAILABLE=true
        DEFER_TO_POST_INSTALL=true
        log "🚀 Post-install optimization detected - will defer heavy operations"
    fi
}

# Launch post-install in background
launch_post_install() {
    if [[ "$POST_INSTALL_AVAILABLE" == "true" ]]; then
        echo ""
        echo -e "${YELLOW}⚡ LAUNCHING POST-INSTALL OPTIMIZATION ⚡${NC}"
        echo ""
        
        # Find post-install.sh
        local post_install_script=""
        if [[ -f "$GRIM_INSTALL_DIR/post-install.sh" ]]; then
            post_install_script="$GRIM_INSTALL_DIR/post-install.sh"
        elif [[ -f "$GRIM_GRAVEYARD/post-install.sh" ]]; then
            post_install_script="$GRIM_GRAVEYARD/post-install.sh"
        elif [[ -f "post-install.sh" ]]; then
            post_install_script="post-install.sh"
        fi
        
        if [[ -n "$post_install_script" ]]; then
            # Copy to graveyard for persistence
            cp "$post_install_script" "$GRIM_GRAVEYARD/post-install.sh"
            chmod +x "$GRIM_GRAVEYARD/post-install.sh"
            
            echo -e "${BLUE}📦 Heavy operations will complete in background:${NC}"
            echo "  • Go compilation and tools"
            echo "  • Node.js and npm packages"
            echo "  • Python virtual environment"
            echo "  • AI model downloads"
            echo "  • Additional optimizations"
            echo ""
            echo -e "${YELLOW}Monitor progress:${NC} tail -f $GRIM_GRAVEYARD/post-install.log"
            echo ""
            
            # Launch in background
            nohup "$GRIM_GRAVEYARD/post-install.sh" --background > "$GRIM_GRAVEYARD/post-install.log" 2>&1 &
            local pid=$!
            echo -e "${GREEN}✅ Post-install optimization started (PID: $pid)${NC}"
            echo ""
            
            # Save PID for reference
            echo $pid > "$GRIM_GRAVEYARD/.post-install.pid"
        else
            warning "Post-install.sh not found - some optimizations skipped"
        fi
    fi
}

