# ============================================================================
# LOGGING FUNCTIONS
# ============================================================================
PROGRESS_LOG_FILE="/tmp/reaper-install.log"

log() {
    echo -e "[$(date '+%H:%M:%S')] $1" >> "$PROGRESS_LOG_FILE"
}

success() {
    echo -e "[$(date '+%H:%M:%S')] ✅ $1" >> "$PROGRESS_LOG_FILE"
}

warning() {
    echo -e "[$(date '+%H:%M:%S')] ⚠️  $1" >> "$PROGRESS_LOG_FILE"
}

error() {
    echo -e "[$(date '+%H:%M:%S')] ❌ $1" >> "$PROGRESS_LOG_FILE"
    exit 1
}

# ============================================================================
# PATH DETERMINATION
# ============================================================================
determine_install_paths() {
    # Try /root/.graveyard first (system-wide, preferred)
    if [[ -w "/root" ]] || mkdir -p "/root/.graveyard" 2>/dev/null; then
        GRIM_GRAVEYARD="/root/.graveyard"
        GRIM_INSTALL_DIR="/root/.graveyard/reaper"
        log "Using system-wide installation: /root/.graveyard/reaper"
    else
        # Fallback to user's home directory
        GRIM_GRAVEYARD="${GRIM_GRAVEYARD:-$HOME/.graveyard}"
        GRIM_INSTALL_DIR="${GRIM_INSTALL_DIR:-$HOME/.graveyard/reaper}"
        log "Using user installation: $HOME/.graveyard/reaper"
    fi
}

# ============================================================================
# PRODUCTION MODE CHECKS
# ============================================================================
check_production_mode() {
    if [[ "${GRIM_PRODUCTION_MODE:-false}" == "true" ]]; then
        log "Running in production mode - applying production enhancements"
        
        # 1. Check if running as root
        if [[ $EUID -ne 0 ]]; then
            error "Production mode requires root privileges"
        fi
        
        # 2. Create a dedicated user for Grim (better security)
        if ! id -u grim >/dev/null 2>&1; then
            log "Creating dedicated 'grim' user for security..."
            useradd -r -s /bin/bash -d /opt/grim -m grim
            success "Created dedicated 'grim' user"
        fi
        
        # Create grim home directory if it doesn't exist
        if [[ ! -d "/opt/grim" ]]; then
            mkdir -p /opt/grim
            chown grim:grim /opt/grim
            chmod 750 /opt/grim
            success "Created grim home directory"
        fi
        
        # 3. Set production environment variables
        export GRIM_INSTALL_USER=grim
        export GRIM_INSTALL_GROUP=grim
        export GRIM_PRODUCTION_MODE=true
        
        log "Production mode enabled - enhanced security and monitoring will be applied"
    fi
}

# ============================================================================
# AFFILIATE SYSTEM
# ============================================================================
register_affiliate() {
    local affiliate_id="$1"
    log "Registering affiliate ID: $affiliate_id"
    
    # Try to register with the affiliate system (accept HTTP 302 redirects)
    local response
    response=$(curl -s -L -w "%{http_code}" "https://rip.grim.so/api/new-afl/$affiliate_id" 2>/dev/null)
    local http_code="${response: -3}"
    local body="${response%???}"
    
    if [[ "$http_code" == "200" ]] || [[ "$http_code" == "201" ]] || [[ "$http_code" == "302" ]]; then
        success "Affiliate ID registered successfully"
        return 0
    else
        warning "Affiliate registration failed (HTTP $http_code) - continuing anyway"
        return 1
    fi
}

generate_affiliate_id() {
    # Get server IP address
    local server_ip
    server_ip=$(curl -s --max-time 5 https://ipinfo.io/ip 2>/dev/null || echo "unknown")
    
    # Generate 8-character hash from IP
    local affiliate_id
    affiliate_id=$(echo "$server_ip" | md5sum | cut -c1-8)
    
    echo "$affiliate_id"
}

