# ============================================================================
# PROGRESS BAR SYSTEM
# ============================================================================

# Progress tracking variables
declare -a PROGRESS_PHASES=()
declare -a PROGRESS_DESCRIPTIONS=()
declare -g CURRENT_PHASE=0
declare -g TOTAL_PHASES=0

# Initialize progress system
initProgressBar() {
    local phases=("$@")
    PROGRESS_PHASES=("${phases[@]}")
    TOTAL_PHASES=${#PROGRESS_PHASES[@]}
    CURRENT_PHASE=0
    
    # Initialize log
    echo "Grim Reaper Installation - $(date)" > "$PROGRESS_LOG_FILE"
}

# Set custom descriptions
setProgressDescriptions() {
    PROGRESS_DESCRIPTIONS=("$@")
}

# Draw progress bar
drawProgressBar() {
    local current="$1"
    local total="$2"
    local phase_name="$3"
    local description="$4"
    
    local percentage=$((current * 100 / total))
    local bar_width=50
    local filled=$((current * bar_width / total))
    local empty=$((bar_width - filled))
    
    # Clear screen and show header
    clear
    echo -e "${BOLD_RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo -e "${BOLD_CYAN}                       GRIM.so INSTALLATION ${NC}"
    echo -e "${BOLD_RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo ""
    
    # Show current phase
    echo -e "${BOLD_PURPLE}Phase ${current}/${total}: ${BOLD_WHITE}${phase_name}${NC}"
    echo -e "${GRAY}${description}${NC}"
    echo ""
    
    # Progress bar with skulls
    local bar=""
    for ((i=0; i<filled; i++)); do
        bar+="💀"
    done
    for ((i=0; i<empty; i++)); do
        bar+="░"
    done
    
    echo -e "${BOLD_CYAN}Progress: [${RED}${bar}${BOLD_CYAN}] ${BOLD_WHITE}${percentage}%${NC}"
    echo ""
    
    # Show small reaper
    echo -e "${DIM}${REAPER_SMALL}${NC}" | sed 's/^/    /'
    echo ""
}

# Update progress bar
updateProgressBar() {
    local phase_name=""
    local description=""
    
    # Get current phase info
    if [[ $CURRENT_PHASE -lt $TOTAL_PHASES ]]; then
        phase_name="${PROGRESS_PHASES[$CURRENT_PHASE]}"
        if [[ $CURRENT_PHASE -lt ${#PROGRESS_DESCRIPTIONS[@]} ]]; then
            description="${PROGRESS_DESCRIPTIONS[$CURRENT_PHASE]}"
        else
            description="Working on ${phase_name}..."
        fi
    fi
    
    # Draw the progress bar
    drawProgressBar "$((CURRENT_PHASE + 1))" "$TOTAL_PHASES" "$phase_name" "$description"
    
    # Log progress
    echo "[$(date '+%H:%M:%S')] Completed phase $((CURRENT_PHASE + 1))/$TOTAL_PHASES: $phase_name" >> "$PROGRESS_LOG_FILE"
    
    # Move to next phase
    ((CURRENT_PHASE++))
    
    # Small delay for visual effect
    sleep 1
}

# ============================================================================
# REAPER ANIMATIONS
# ============================================================================

# Animate reaper walking (runs continuously until stopped)
startWalkingReaper() {
    local duration="${1:-10}"
    local frame=1
    local position=0
    local width=80
    
    # Run animation continuously until killed
    while true; do
        # Save cursor position
        printf "\033[s"
        
        # Move to bottom of screen for animation
        printf "\033[25;1H"
        
        # Clear animation area
        for i in {1..10}; do
            printf "\033[K\n"
        done
        
        # Move back to animation start
        printf "\033[25;1H"
        
        # Draw walking reaper
        local reaper_art=""
        if [[ $frame -eq 1 ]]; then
            reaper_art="$REAPER_WALK1"
            frame=2
        else
            reaper_art="$REAPER_WALK2"
            frame=1
        fi
        
        # Add padding for position
        echo "$reaper_art" | while IFS= read -r line; do
            printf "%${position}s${GRAY}%s${NC}\n" "" "$line"
        done
        
        # Move position
        position=$((position + 1))
        if [[ $position -gt $((width - 30)) ]]; then
            position=0
        fi
        
        # Restore cursor position
        printf "\033[u"
        
        sleep 0.3  # Slightly faster
    done &
}

# Animate scythe swinging (runs continuously until stopped)
startScytheAnimation() {
    local duration="${1:-5}"
    local frame=1
    
    # Run animation continuously until killed
    while true; do
        # Save cursor position
        printf "\033[s"
        
        # Move to bottom right for scythe animation
        printf "\033[15;50H"
        
        # Clear animation area
        for i in {1..15}; do
            printf "\033[K\n"
        done
        
        # Move back to animation start
        printf "\033[15;50H"
        
        # Draw scythe animation
        local scythe_art=""
        if [[ $frame -eq 1 ]]; then
            scythe_art="$REAPER_SCYTHE1"
            frame=2
        else
            scythe_art="$REAPER_SCYTHE2"
            frame=1
        fi
        
        echo "$scythe_art" | while IFS= read -r line; do
            echo -e "${RED}$line${NC}"
        done
        
        # Restore cursor position
        printf "\033[u"
        
        sleep 0.4  # Slightly faster
    done &
}

# Spooky loading animation that runs continuously until stopped
startLoadingAnimation() {
    local duration="${1:-5}"
    local spinner=("⠋" "⠙" "⠹" "⠸" "⠼" "⠴" "⠦" "⠧" "⠇" "⠏")
    local skulls=("💀" "☠️" "👻" "🦴")
    local count=0
    
    # Run animation continuously until killed
    while true; do
        # Save cursor position
        printf "\033[s"
        
        # Move to loading area
        printf "\033[20;1H"
        printf "\033[K"  # Clear line
        
        # Show loading with skulls and spinner
        local spin_char=${spinner[$((count % ${#spinner[@]}))]}
        local skull_char=${skulls[$((count % ${#skulls[@]}))]}
        
        printf "${PURPLE}%s ${DIM}Working... ${spin_char} %s${NC}" "$skull_char" "$skull_char"
        
        # Restore cursor position
        printf "\033[u"
        
        sleep 0.15  # Faster animation
        ((count++))
    done &
}

# Stop all background animations and clean up display
stopAnimations() {
    # Kill all background jobs (animations)
    jobs -p | xargs -r kill -TERM 2>/dev/null || true
    sleep 0.1
    jobs -p | xargs -r kill -KILL 2>/dev/null || true
    wait 2>/dev/null || true
    
    # Clean display cleanup (less aggressive)
    printf "\033[s"  # Save cursor position
    
    # Clear loading line
    printf "\033[20;1H\033[K"
    
    # Clear animation area
    printf "\033[25;1H"
    for i in {1..10}; do
        printf "\033[K\n"  # Clear animation lines
    done
    
    printf "\033[u"  # Restore cursor position
}

# ============================================================================
# ANIMATION WRAPPER FUNCTIONS
# ============================================================================

# Execute function with reaper entertainment
executeWithReaper() {
    local func_name="$1"
    local animation_type="${2:-loading}"  # loading, walk, scythe
    local duration="${3:-5}"
    
    # Start appropriate animation
    case "$animation_type" in
        "walk")
            startWalkingReaper "$duration" ;;
        "scythe")
            startScytheAnimation "$duration" ;;
        *)
            startLoadingAnimation "$duration" ;;
    esac
    
    local anim_pid=$!
    
    # Minimal cleanup to prevent interference
    printf "\033[s"  # Save cursor position
    printf "\033[20;1H\033[K"  # Clear just the loading line
    printf "\033[u"  # Restore cursor position
    
    # Execute the actual function (with controlled output)
    if command -v "$func_name" >/dev/null 2>&1; then
        # Suppress function output but allow our animations to continue
        "$func_name" >/dev/null 2>&1
        local exit_code=$?
    else
        echo "Warning: Function '$func_name' not found" >> "$PROGRESS_LOG_FILE"
        local exit_code=1
    fi
    
    # Stop animations
    stopAnimations
    
    # Update progress bar
    updateProgressBar
    
    # Handle errors
    if [[ $exit_code -ne 0 ]]; then
        showError "$func_name" "$exit_code"
        return $exit_code
    fi
    
    return 0
}

