# ============================================================================
# SYSTEM MODULE
# ============================================================================
# 🗡️ GRIM REAPER - SYSTEM MODULE
# System detection and package installation functions

# ============================================================================
# SYSTEM DETECTION
# ============================================================================
detect_system() {
    log "Detecting system configuration..."
    
    OS=$(uname -s | tr '[:upper:]' '[:lower:]')
    ARCH=$(uname -m)
    
    if [[ -f /etc/os-release ]]; then
        . /etc/os-release
        DISTRO=${ID:-unknown}
        VERSION=${VERSION_ID:-unknown}
    else
        DISTRO="unknown"
        VERSION="unknown"
    fi
    
    log "System: $OS ($DISTRO $VERSION) on $ARCH"
    
    # Check if running as root
    if [[ $EUID -ne 0 ]]; then
        warning "Not running as root - some installations may require sudo"
        SUDO="sudo"
    else
        SUDO=""
    fi
}

# ============================================================================
# DOWNLOAD AND EXTRACT
# ============================================================================
download_grim() {
    log "Downloading Grim Reaper..."
    
    # Create temporary directory
    TEMP_DIR=$(mktemp -d)
    cd "$TEMP_DIR"
    
    # Download the latest build
    if [[ "$GRIM_VERSION" == "latest" ]]; then
        log "Downloading latest build..."
        curl -L -o grim-reaper.tar.gz "$GRIM_DISTRIBUTION_URL/latest.tar.gz"
    else
        log "Downloading version: $GRIM_VERSION"
        curl -L -o grim-reaper.tar.gz "$GRIM_DISTRIBUTION_URL/latest.tar.gz"
    fi
    
    # Verify download
    if [[ ! -f "grim-reaper.tar.gz" ]]; then
        error "Failed to download Grim Reaper"
    fi
    
    # Extract
    log "Extracting Grim Reaper..."
    tar -xzf grim-reaper.tar.gz
    
    # Find the extracted directory - handle both old and new formats
    GRIM_BUILD_DIR=$(find . -maxdepth 1 -name "grim-reaper-*" -type d | head -1)
    if [[ -z "$GRIM_BUILD_DIR" ]]; then
        # Check for new graveyard format
        if [[ -d "./graveyard/reaper" ]]; then
            GRIM_BUILD_DIR="graveyard/reaper"
            log "Found new graveyard format - using graveyard/reaper"
        else
            error "Could not find extracted Grim Reaper directory (neither grim-reaper-* nor graveyard/reaper found)"
        fi
    fi
    
    # Make sure grim_throne.sh is executable
    if [[ -f "$GRIM_BUILD_DIR/grim_throne.sh" ]]; then
        chmod +x "$GRIM_BUILD_DIR/grim_throne.sh"
        log "Made grim_throne.sh executable"
    fi
    if [[ -f "$GRIM_BUILD_DIR/throne/grim_throne.sh" ]]; then
        chmod +x "$GRIM_BUILD_DIR/throne/grim_throne.sh"
        log "Made throne/grim_throne.sh executable"
    fi
    
    # Clean up the path (remove ./ prefix if present)
    GRIM_BUILD_DIR="${GRIM_BUILD_DIR#./}"
    
    success "Grim Reaper downloaded and extracted"
    # Return the full path to the build directory (clean output)
    printf "%s" "$TEMP_DIR/$GRIM_BUILD_DIR"
}

# ============================================================================
# PACKAGE INSTALLATION HELPERS
# ============================================================================

# Install package with error handling
install_package() {
    local package_name="$1"
    local description="${2:-$package_name}"
    
    # Check if already installed first to avoid unnecessary operations
    if dpkg -l "$package_name" 2>/dev/null | grep -q "^ii"; then
        log "✓ $description already installed"
        return 0
    fi
    
    log "Installing $description..."
    
    if command -v apt >/dev/null 2>&1; then
        if [[ $EUID -ne 0 ]]; then
            if sudo apt install -y "$package_name"; then
                success "$description installed via apt"
                return 0
            fi
        else
            if apt install -y "$package_name"; then
                success "$description installed via apt"
                return 0
            fi
        fi
    elif command -v yum >/dev/null 2>&1; then
        if [[ $EUID -ne 0 ]]; then
            if sudo yum install -y "$package_name"; then
                success "$description installed via yum"
                return 0
            fi
        else
            if yum install -y "$package_name"; then
                success "$description installed via yum"
                return 0
            fi
        fi
    elif command -v dnf >/dev/null 2>&1; then
        if [[ $EUID -ne 0 ]]; then
            if sudo dnf install -y "$package_name"; then
                success "$description installed via dnf"
                return 0
            fi
        else
            if dnf install -y "$package_name"; then
                success "$description installed via dnf"
                return 0
            fi
        fi
    fi
    
    warning "Failed to install $description - no supported package manager found or installation failed"
    return 1
}

# Install multiple packages
install_packages() {
    local packages=("$@")
    local failed_packages=()
    
    for package in "${packages[@]}"; do
        if ! install_package "$package"; then
            failed_packages+=("$package")
        fi
    done
    
    if [[ ${#failed_packages[@]} -gt 0 ]]; then
        warning "Failed to install packages: ${failed_packages[*]}"
        return 1
    fi
    
    return 0
}

# Check if command exists, install if not
ensure_command() {
    local command_name="$1"
    local package_name="${2:-$command_name}"
    local description="${3:-$command_name}"
    
    if command -v "$command_name" >/dev/null 2>&1; then
        log "$description already installed: $($command_name --version 2>/dev/null | head -1 || echo 'version unknown')"
        return 0
    fi
    
    log "$description not found - installing..."
    install_package "$package_name" "$description"
}

# ============================================================================
# CORE DEPENDENCIES INSTALLATION
# ============================================================================

install_core_dependencies() {
    log "Installing core dependencies..."
    
    # SQLite3
    ensure_command "sqlite3" "sqlite3" "SQLite3"
    
    # Python3 and pip
    ensure_command "python3" "python3 python3-pip python3-dev python3-venv" "Python3 with dev tools"
    
    # Auto-backup dependencies (compression tools handled separately)
    local backup_deps=("openssl" "jq")
    log "Installing auto-backup dependencies..."
    install_packages "${backup_deps[@]}"
    
    # Development tools
    local dev_tools=("curl" "wget" "git" "build-essential" "gcc")
    log "Installing development tools..."
    install_packages "${dev_tools[@]}" || warning "Some development tools may not be available"
    
    success "Core dependencies installation completed"
}

