# ============================================================================
# COMPRESSION COMMAND DEPENDENCIES
# ============================================================================

install_compression_dependencies() {
    log "Installing compression command dependencies..."
    
    # Install all compression tools in one go (more efficient)
    local compression_packages=("gzip" "bzip2" "xz-utils" "lz4" "zstd" "lzop" "p7zip-full" "bc")
    log "Installing compression tools package bundle..."
    install_packages "${compression_packages[@]}" || warning "Some compression tools may not be available"
    
    # Quick verification (less verbose)
    local compression_tools=("gzip" "bzip2" "xz" "lz4" "zstd" "lzop" "7z" "bc")
    local available_tools=0
    
    for tool in "${compression_tools[@]}"; do
        if command -v "$tool" >/dev/null 2>&1; then
            ((available_tools++))
        fi
    done
    
    success "Compression dependencies: $available_tools/${#compression_tools[@]} tools available"
} 


# ============================================================================
# HEALTH COMMAND DEPENDENCIES
# ============================================================================

install_health_dependencies() {
    log "Installing health command dependencies..."
    
    # System monitoring utilities
    local monitoring_tools=("net-tools" "iputils-ping" "dnsutils" "procps" "coreutils")
    log "Installing system monitoring utilities..."
    install_packages "${monitoring_tools[@]}"
    
    # Ensure critical health check commands
    ensure_command "ping" "iputils-ping" "Network connectivity testing"
    ensure_command "nslookup" "dnsutils" "DNS resolution testing"
    ensure_command "df" "coreutils" "Disk usage monitoring"
    ensure_command "free" "procps" "Memory usage monitoring"
    ensure_command "uptime" "procps" "System load monitoring"
    
    # Network tools for advanced health checks
    if ! command -v "ip" >/dev/null 2>&1 && ! command -v "ifconfig" >/dev/null 2>&1; then
        log "Installing network interface tools..."
        install_package "iproute2" "Network interface monitoring (ip command)" ||         install_package "net-tools" "Network interface monitoring (ifconfig command)"
    fi
    
    # Verify health command dependencies
    log "Verifying health command tools..."
    local health_tools=("ping" "df" "free" "uptime" "systemctl")
    local available_health_tools=0
    local total_health_tools=${#health_tools[@]}
    
    for tool in "${health_tools[@]}"; do
        if command -v "$tool" >/dev/null 2>&1; then
            ((available_health_tools++))
            log "✓ $tool available"
        else
            warning "✗ $tool not available"
        fi
    done
    
    success "Health dependencies: $available_health_tools/$total_health_tools tools available"
} 


