# ============================================================================
# PYTHON DEPENDENCIES FOR GRIM COMMANDS
# ============================================================================

install_grim_python_dependencies() {
    log "Installing Python dependencies for Grim commands..."
    
    # Ensure Python virtual environment tools
    ensure_command "python3" "python3 python3-pip python3-venv python3-dev" "Python3 with development tools"
    
    # Check if virtual environment exists, create if needed
    if [[ -d "$GRIM_INSTALL_DIR/grim_venv" ]]; then
        log "Using existing Python virtual environment"
    else
        log "Creating Python virtual environment for Grim..."
        # Ensure the install directory exists before trying to cd into it
        mkdir -p "$GRIM_INSTALL_DIR"
        cd "$GRIM_INSTALL_DIR"
        python3 -m venv grim_venv || {
            warning "venv creation failed, trying alternative methods"
            # Fallback methods handled by existing setup_python_environment function
        }
    fi
    
    # Install critical Python packages if requirements.txt exists
    if [[ -f "$GRIM_INSTALL_DIR/py_grim/requirements.txt" ]]; then
        log "Installing Python packages from requirements.txt..."
        mkdir -p "$GRIM_INSTALL_DIR"
        cd "$GRIM_INSTALL_DIR"
        if [[ -f "grim_venv/bin/activate" ]]; then
            source grim_venv/bin/activate
            pip install --upgrade pip
            pip install -r py_grim/requirements.txt || warning "Some Python packages may have failed to install"
        else
            warning "Virtual environment not available, installing system-wide"
            pip3 install --break-system-packages -r py_grim/requirements.txt || warning "Some Python packages may have failed to install"
        fi
    else
        log "No requirements.txt found, skipping Python package installation"
    fi
    
    # Verify critical Python functionality
    log "Verifying Python environment..."
    if python3 -c "import sys; print('Python', sys.version)" >/dev/null 2>&1; then
        log "✓ Python3 working"
    else
        warning "✗ Python3 verification failed"
    fi
    
    success "Python dependencies installation completed"
} 


install_grim_command_dependencies() {
    log "Installing all Grim command dependencies..."
    
    # Update package lists once at the beginning for efficiency
    log "Updating package lists..."
    if [[ $EUID -ne 0 ]]; then
        sudo apt update -qq || warning "Package list update failed"
    else
        apt update -qq || warning "Package list update failed"
    fi
    
    # Core command dependencies
    install_compression_dependencies || warning "Compression dependencies had issues"
    install_health_dependencies || warning "Health dependencies had issues"
    install_audit_dependencies || warning "Audit dependencies had issues"
    install_security_dependencies || warning "Security dependencies had issues"
    
    # Advanced features
    install_gateway_dependencies || warning "Gateway dependencies had issues"
    install_scanner_dependencies || warning "Scanner dependencies had issues"
    install_docs_dependencies || warning "Docs dependencies had issues"
    install_cloud_dependencies || warning "Cloud dependencies had issues"
    install_test_dependencies || warning "Test dependencies had issues"
    
    # Data management
    install_dedup_dependencies || warning "Dedup dependencies had issues"
    install_transfer_dependencies || warning "Transfer dependencies had issues"
    install_restore_dependencies || warning "Restore dependencies had issues"
    install_verify_dependencies || warning "Verify dependencies had issues"
    install_log_dependencies || warning "Log dependencies had issues"
    install_encrypt_dependencies || warning "Encrypt dependencies had issues"
    
    # Infrastructure
    install_distributed_dependencies || warning "Distributed dependencies had issues"
    install_scythe_dependencies || warning "Scythe dependencies had issues"
    
    # Python environment
    install_grim_python_dependencies || warning "Python dependencies had issues"
    
    success "All 19 Grim command dependency modules completed!"
}

# ============================================================================
# LANGUAGE RUNTIME INSTALLATION
# ============================================================================

install_go() {
    if command -v go >/dev/null 2>&1; then
        log "Go already installed: $(go version)"
        return 0
    fi
    
    log "Go not found - installing Go..."
    GO_VERSION="1.22.2"
    GO_ARCH="amd64"
    if [[ "$(uname -m)" == "aarch64" ]]; then
        GO_ARCH="arm64"
    elif [[ "$(uname -m)" == "armv7l" ]]; then
        GO_ARCH="armv6l"
    fi
    
    # Try package manager first
    if install_package "golang-go" "Go programming language"; then
        return 0
    fi
    
    # Download from official source if package manager fails
    log "Package manager installation failed - downloading Go from official source..."
    cd /tmp
    GO_TARBALL="go${GO_VERSION}.linux-${GO_ARCH}.tar.gz"
    GO_URL="https://golang.org/dl/${GO_TARBALL}"
    
    if curl -L -o "$GO_TARBALL" "$GO_URL"; then
        if [[ $EUID -ne 0 ]]; then
            sudo rm -rf /usr/local/go
            sudo tar -C /usr/local -xzf "$GO_TARBALL"
            sudo chown -R root:root /usr/local/go
        else
            rm -rf /usr/local/go
            tar -C /usr/local -xzf "$GO_TARBALL"
        fi
        
        # Add to PATH
        if ! grep -q "/usr/local/go/bin" /etc/environment 2>/dev/null; then
            echo 'PATH="/usr/local/go/bin:$PATH"' | sudo tee -a /etc/environment
        fi
        export PATH="/usr/local/go/bin:$PATH"
        
        success "Go ${GO_VERSION} installed from official source"
        return 0
    else
        warning "Failed to download Go from official source"
        return 1
    fi
}

install_nodejs() {
    if command -v node >/dev/null 2>&1; then
        log "Node.js already installed: $(node --version)"
        return 0
    fi
    
    log "Node.js not found - installing Node.js..."
    
    # Try package manager first
    if install_package "nodejs npm" "Node.js and npm"; then
        return 0
    fi
    
    # Use NodeSource repository if package manager fails
    log "Package manager installation failed - using NodeSource repository..."
    if command -v apt >/dev/null 2>&1; then
        if [[ $EUID -ne 0 ]]; then
            curl -fsSL https://deb.nodesource.com/setup_20.x | sudo -E bash -
            sudo apt-get install -y nodejs
        else
            curl -fsSL https://deb.nodesource.com/setup_20.x | bash -
            apt-get install -y nodejs
        fi
        
        if command -v node >/dev/null 2>&1; then
            success "Node.js installed via NodeSource: $(node --version)"
            return 0
        fi
    elif command -v yum >/dev/null 2>&1; then
        if [[ $EUID -ne 0 ]]; then
            curl -fsSL https://rpm.nodesource.com/setup_20.x | sudo bash -
            sudo yum install -y nodejs
        else
            curl -fsSL https://rpm.nodesource.com/setup_20.x | bash -
            yum install -y nodejs
        fi
        
        if command -v node >/dev/null 2>&1; then
            success "Node.js installed via NodeSource: $(node --version)"
            return 0
        fi
    fi
    
    warning "Failed to install Node.js"
    return 1
}

