# Safe backup, restore, and data preservation functions

# ============================================================================
# EXISTING INSTALLATION DETECTION
# ============================================================================

detect_existing_installation() {
    log "Checking for existing Grim installation..."
    
    if [[ -f "/usr/local/bin/grim" ]]; then
        EXISTING_GRIM_CMD="/usr/local/bin/grim"
        EXISTING_GRIM_ROOT=$(readlink -f "$EXISTING_GRIM_CMD" | xargs dirname 2>/dev/null || echo "")
        if [[ -n "$EXISTING_GRIM_ROOT" && -d "$EXISTING_GRIM_ROOT" ]]; then
            success "Found existing Grim installation at: $EXISTING_GRIM_ROOT"
            return 0
        fi
    fi
    
    # Check common installation paths
    for path in "/root/.graveyard/reaper" "$HOME/.graveyard/reaper" "/opt/reaper"; do
        if [[ -d "$path" && -f "$path/grim_throne.sh" ]]; then
            EXISTING_GRIM_ROOT="$path"
            success "Found existing Grim installation at: $EXISTING_GRIM_ROOT"
            return 0
        fi
    done
    
    log "No existing installation detected - proceeding with fresh install"
    return 1
}

# ============================================================================
# BACKUP CREATION
# ============================================================================

create_installation_backup() {
    local install_dir="$1"
    local backup_dir="$install_dir.backup.$(date +%Y%m%d_%H%M%S)"
    
    log "Creating backup of existing installation..."
    log "Backup location: $backup_dir"
    
    # Create backup directory
    $SUDO mkdir -p "$backup_dir"
    
    # Copy existing installation
    if $SUDO cp -r "$install_dir"/* "$backup_dir/" 2>/dev/null; then
        success "Installation backed up to: $backup_dir"
        echo "$backup_dir" > /tmp/grim_backup_location
        return 0
    else
        error "Failed to create backup - aborting update"
    fi
}

# ============================================================================
# ENHANCED DATA PRESERVATION
# ============================================================================

preserve_user_data() {
    local install_dir="$1"
    local temp_preserve="/tmp/grim_preserve_$(date +%s)"
    
    log "Preserving critical user data with enhanced protection..."
    mkdir -p "$temp_preserve"
    
    # Create a manifest of what we're preserving
    local manifest_file="$temp_preserve/preservation_manifest.txt"
    echo "# Grim Reaper Data Preservation Manifest" > "$manifest_file"
    echo "# Generated: $(date)" >> "$manifest_file"
    echo "# Source: $install_dir" >> "$manifest_file"
    echo "" >> "$manifest_file"
    
    # Preserve databases (CRITICAL - never overwrite)
    if [[ -d "$install_dir/db" ]]; then
        log "Preserving databases (CRITICAL DATA)..."
        if cp -r "$install_dir/db" "$temp_preserve/" 2>/dev/null; then
            echo "✅ PRESERVED: databases (db/)" >> "$manifest_file"
            local db_count=$(find "$install_dir/db" -name "*.db" -o -name "*.sqlite*" | wc -l)
            local db_size=$(du -sh "$install_dir/db" 2>/dev/null | cut -f1)
            echo "   - Database files: $db_count" >> "$manifest_file"
            echo "   - Total size: $db_size" >> "$manifest_file"
            success "Databases preserved (${db_count} files, ${db_size})"
        else
            echo "❌ FAILED: databases (db/)" >> "$manifest_file"
            warning "Could not preserve databases - MANUAL BACKUP RECOMMENDED"
        fi
    else
        echo "ℹ️  SKIPPED: databases (not found)" >> "$manifest_file"
        log "No databases directory found"
    fi
    
    # Preserve backups (CRITICAL - user's existing backups)
    if [[ -d "$install_dir/backups" ]]; then
        log "Preserving user backups (CRITICAL DATA)..."
        if cp -r "$install_dir/backups" "$temp_preserve/" 2>/dev/null; then
            echo "✅ PRESERVED: backups (backups/)" >> "$manifest_file"
            local backup_count=$(find "$install_dir/backups" -type f | wc -l)
            local backup_size=$(du -sh "$install_dir/backups" 2>/dev/null | cut -f1)
            echo "   - Backup files: $backup_count" >> "$manifest_file"
            echo "   - Total size: $backup_size" >> "$manifest_file"
            success "User backups preserved (${backup_count} files, ${backup_size})"
        else
            echo "❌ FAILED: backups (backups/)" >> "$manifest_file"
            warning "Could not preserve backups - MANUAL BACKUP RECOMMENDED"
        fi
    else
        echo "ℹ️  SKIPPED: backups (not found)" >> "$manifest_file"
        log "No backups directory found"
    fi
    
    # Preserve logs (IMPORTANT - for troubleshooting)
    if [[ -d "$install_dir/logs" ]]; then
        log "Preserving logs..."
        if cp -r "$install_dir/logs" "$temp_preserve/" 2>/dev/null; then
            echo "✅ PRESERVED: logs (logs/)" >> "$manifest_file"
            local log_count=$(find "$install_dir/logs" -name "*.log" | wc -l)
            echo "   - Log files: $log_count" >> "$manifest_file"
            success "Logs preserved (${log_count} files)"
        else
            echo "❌ FAILED: logs (logs/)" >> "$manifest_file"
            warning "Could not preserve logs"
        fi
    else
        echo "ℹ️  SKIPPED: logs (not found)" >> "$manifest_file"
    fi
    
    # Preserve .graveyard user data (CRITICAL - user's actual data)
    if [[ -d "$install_dir/.graveyard" ]]; then
        log "Preserving .graveyard user data (CRITICAL DATA)..."
        if cp -r "$install_dir/.graveyard" "$temp_preserve/" 2>/dev/null; then
            echo "✅ PRESERVED: .graveyard user data (.graveyard/)" >> "$manifest_file"
            local graveyard_size=$(du -sh "$install_dir/.graveyard" 2>/dev/null | cut -f1)
            echo "   - Total size: $graveyard_size" >> "$manifest_file"
            success ".graveyard user data preserved (${graveyard_size})"
        else
            echo "❌ FAILED: .graveyard user data (.graveyard/)" >> "$manifest_file"
            warning "Could not preserve .graveyard data - MANUAL BACKUP RECOMMENDED"
        fi
    else
        echo "ℹ️  SKIPPED: .graveyard (not found)" >> "$manifest_file"
    fi
    
    # Preserve custom configurations (merge-safe)
    if [[ -d "$install_dir/config" ]]; then
        log "Preserving custom configurations..."
        mkdir -p "$temp_preserve/config"
        
        # Preserve user-specific config files (not default configs)
        find "$install_dir/config" \( -name "*.user.*" -o -name "*.local.*" -o -name "*.custom.*" \) -exec cp {} "$temp_preserve/config/" \; 2>/dev/null
        
        # Also preserve any config files that have been modified recently (user customizations)
        find "$install_dir/config" -type f -mtime -30 -exec cp {} "$temp_preserve/config/" \; 2>/dev/null
        
        local config_count=$(find "$temp_preserve/config" -type f | wc -l)
        if [[ $config_count -gt 0 ]]; then
            echo "✅ PRESERVED: custom configurations (config/) - $config_count files" >> "$manifest_file"
            success "Custom configurations preserved (${config_count} files)"
        else
            echo "ℹ️  SKIPPED: configurations (no custom configs found)" >> "$manifest_file"
        fi
    else
        echo "ℹ️  SKIPPED: configurations (not found)" >> "$manifest_file"
    fi
    
    # Preserve virtual environment (IMPORTANT - for dependencies)
    if [[ -d "$install_dir/grim_venv" ]]; then
        log "Preserving Python virtual environment..."
        if cp -r "$install_dir/grim_venv" "$temp_preserve/" 2>/dev/null; then
            echo "✅ PRESERVED: virtual environment (grim_venv/)" >> "$manifest_file"
            success "Virtual environment preserved"
        else
            echo "❌ FAILED: virtual environment (grim_venv/)" >> "$manifest_file"
            warning "Could not preserve virtual environment - will be recreated"
        fi
    else
        echo "ℹ️  SKIPPED: virtual environment (not found)" >> "$manifest_file"
    fi
    
    # Preserve any additional user data directories
    for user_dir in "user_data" "custom" "local" "cache" "tmp/user" "exports" "imports"; do
        if [[ -d "$install_dir/$user_dir" ]]; then
            log "Preserving additional user directory: $user_dir"
            if cp -r "$install_dir/$user_dir" "$temp_preserve/" 2>/dev/null; then
                echo "✅ PRESERVED: additional user data ($user_dir/)" >> "$manifest_file"
                success "Additional user data preserved: $user_dir"
            else
                echo "❌ FAILED: additional user data ($user_dir/)" >> "$manifest_file"
                warning "Could not preserve $user_dir"
            fi
        fi
    done
    
    # Preserve any .env files or environment configurations
    for env_file in ".env" ".env.local" ".env.user" "environment.conf" "grim.conf"; do
        if [[ -f "$install_dir/$env_file" ]]; then
            log "Preserving environment file: $env_file"
            if cp "$install_dir/$env_file" "$temp_preserve/" 2>/dev/null; then
                echo "✅ PRESERVED: environment file ($env_file)" >> "$manifest_file"
                success "Environment file preserved: $env_file"
            else
                echo "❌ FAILED: environment file ($env_file)" >> "$manifest_file"
                warning "Could not preserve $env_file"
            fi
        fi
    done
    
    # Create a backup verification file
    echo "" >> "$manifest_file"
    echo "# Verification Info" >> "$manifest_file"
    echo "Preservation completed: $(date)" >> "$manifest_file"
    echo "Total preserved size: $(du -sh "$temp_preserve" 2>/dev/null | cut -f1)" >> "$manifest_file"
    echo "Preservation location: $temp_preserve" >> "$manifest_file"
    
    echo "$temp_preserve" > /tmp/grim_preserve_location
    success "User data preserved to: $temp_preserve"
    
    # Show what was preserved
    echo ""
    echo -e "${CYAN}📋 PRESERVATION SUMMARY:${NC}"
    cat "$manifest_file" | grep -E "^✅|^❌|^ℹ️" | while read -r line; do
        if [[ $line == *"✅"* ]]; then
            echo -e "${GREEN}$line${NC}"
        elif [[ $line == *"❌"* ]]; then
            echo -e "${RED}$line${NC}"
        else
            echo -e "${YELLOW}$line${NC}"
        fi
    done
    echo ""
}

# ============================================================================
# DATA RESTORATION
# ============================================================================

restore_user_data() {
    local install_dir="$1"
    local preserve_dir
    
    if [[ -f "/tmp/grim_preserve_location" ]]; then
        preserve_dir=$(cat /tmp/grim_preserve_location)
        
        if [[ -d "$preserve_dir" ]]; then
            log "Restoring preserved user data with enhanced safety..."
            
            # Read the preservation manifest
            local manifest_file="$preserve_dir/preservation_manifest.txt"
            if [[ -f "$manifest_file" ]]; then
                log "Found preservation manifest - using guided restoration"
                echo -e "${CYAN}📋 RESTORATION PLAN:${NC}"
                cat "$manifest_file" | grep "✅ PRESERVED:" | while read -r line; do
                    echo -e "${GREEN}$line${NC}"
                done
                echo ""
            fi
            
            # Restore databases (HIGHEST PRIORITY)
            if [[ -d "$preserve_dir/db" ]]; then
                log "Restoring databases (CRITICAL DATA)..."
                $SUDO mkdir -p "$install_dir/db"
                if $SUDO cp -r "$preserve_dir/db"/* "$install_dir/db/" 2>/dev/null; then
                    success "Databases restored successfully"
                    local restored_db_count=$(find "$install_dir/db" -name "*.db" -o -name "*.sqlite*" | wc -l)
                    log "Verified: ${restored_db_count} database files restored"
                else
                    warning "Database restoration failed - continuing..."
                fi
            fi
            
            # Restore backups (HIGHEST PRIORITY)
            if [[ -d "$preserve_dir/backups" ]]; then
                log "Restoring user backups (CRITICAL DATA)..."
                $SUDO mkdir -p "$install_dir/backups"
                if $SUDO cp -r "$preserve_dir/backups"/* "$install_dir/backups/" 2>/dev/null; then
                    success "User backups restored successfully"
                    local restored_backup_count=$(find "$install_dir/backups" -type f | wc -l)
                    log "Verified: ${restored_backup_count} backup files restored"
                else
                    warning "Backup restoration failed - continuing..."
                fi
            fi
            
            # Restore logs
            if [[ -d "$preserve_dir/logs" ]]; then
                log "Restoring logs..."
                $SUDO mkdir -p "$install_dir/logs"
                $SUDO cp -r "$preserve_dir/logs"/* "$install_dir/logs/" 2>/dev/null || true
            fi
            
            # Restore .graveyard user data
            if [[ -d "$preserve_dir/.graveyard" ]]; then
                log "Restoring .graveyard user data (CRITICAL DATA)..."
                $SUDO mkdir -p "$install_dir/.graveyard"
                if $SUDO cp -r "$preserve_dir/.graveyard"/* "$install_dir/.graveyard/" 2>/dev/null; then
                    success ".graveyard user data restored successfully"
                else
                    warning "Failed to restore .graveyard data - continuing..."
                fi
            fi
            
            # Restore configurations (MERGE MODE - don't overwrite new defaults)
            if [[ -d "$preserve_dir/config" ]]; then
                log "Restoring custom configurations (merge mode)..."
                $SUDO mkdir -p "$install_dir/config"
                
                # Only restore user-specific configs, don't overwrite new default configs
                find "$preserve_dir/config" -name "*.user.*" -o -name "*.local.*" -o -name "*.custom.*" | while read -r config_file; do
                    local filename=$(basename "$config_file")
                    if $SUDO cp "$config_file" "$install_dir/config/" 2>/dev/null; then
                        log "Restored custom config: $filename"
                    fi
                done
                
                success "Custom configurations restored (merge mode)"
            fi
            
            # Restore virtual environment if it was preserved
            if [[ -d "$preserve_dir/grim_venv" ]]; then
                log "Restoring Python virtual environment..."
                if $SUDO cp -r "$preserve_dir/grim_venv" "$install_dir/" 2>/dev/null; then
                    success "Virtual environment restored"
                    if [[ -f "$install_dir/grim_venv/bin/activate" ]]; then
                        log "Virtual environment verified and ready"
                    else
                        warning "Virtual environment may need to be recreated"
                    fi
                else
                    warning "Could not restore virtual environment - will be recreated"
                fi
            fi
            
            # Restore additional user data directories
            for user_dir in "user_data" "custom" "local" "cache" "exports" "imports"; do
                if [[ -d "$preserve_dir/$user_dir" ]]; then
                    log "Restoring additional user directory: $user_dir"
                    $SUDO mkdir -p "$install_dir/$user_dir"
                    if $SUDO cp -r "$preserve_dir/$user_dir"/* "$install_dir/$user_dir/" 2>/dev/null; then
                        success "Additional user data restored: $user_dir"
                    else
                        warning "Could not restore all data from $user_dir"
                    fi
                fi
            done
            
            # Restore environment files
            for env_file in ".env" ".env.local" ".env.user" "environment.conf" "grim.conf"; do
                if [[ -f "$preserve_dir/$env_file" ]]; then
                    log "Restoring environment file: $env_file"
                    if $SUDO cp "$preserve_dir/$env_file" "$install_dir/" 2>/dev/null; then
                        success "Environment file restored: $env_file"
                    else
                        warning "Could not restore $env_file"
                    fi
                fi
            done
            
            # Fix permissions after restoration
            log "Fixing permissions after restoration..."
            $SUDO chown -R root:root "$install_dir" 2>/dev/null || true
            $SUDO chmod -R 755 "$install_dir" 2>/dev/null || true
            
            # Make sure critical directories have correct permissions
            $SUDO chmod 700 "$install_dir/db" 2>/dev/null || true
            $SUDO chmod 755 "$install_dir/backups" 2>/dev/null || true
            $SUDO chmod 755 "$install_dir/.graveyard" 2>/dev/null || true
            
            success "User data restoration process completed"
            
            # Clean up temporary preservation directory
            log "Cleaning up temporary preservation files..."
            rm -rf "$preserve_dir"
            rm -f /tmp/grim_preserve_location
            success "Cleanup completed"
        else
            warning "Preservation directory not found - no user data to restore"
        fi
    else
        log "No preserved data found - this may be a fresh installation"
    fi
}

# ============================================================================
# SERVICE MANAGEMENT
# ============================================================================

stop_services() {
    log "Stopping Grim services before update..."
    
    # Stop systemd services if they exist
    if systemctl is-active --quiet grim.service 2>/dev/null; then
        log "Stopping grim.service..."
        $SUDO systemctl stop grim.service
    fi
    
    if systemctl is-active --quiet grim-storage-enforcement.service 2>/dev/null; then
        log "Stopping grim-storage-enforcement.service..."
        $SUDO systemctl stop grim-storage-enforcement.service
    fi
    
    # Stop any running Grim processes
    if pgrep -f "grim" >/dev/null 2>&1; then
        log "Stopping running Grim processes..."
        $SUDO pkill -f "grim" 2>/dev/null || warning "Could not stop all Grim processes"
        sleep 2
    fi
    
    success "Services stopped"
}

restart_services() {
    log "Restarting Grim services after update..."
    
    # Reload systemd daemon
    $SUDO systemctl daemon-reload
    
    # Start services if they were configured
    if [[ -f "/etc/systemd/system/grim.service" ]]; then
        log "Starting grim.service..."
        $SUDO systemctl start grim.service
    fi
    
    if [[ -f "/etc/systemd/system/grim-storage-enforcement.service" ]]; then
        log "Starting grim-storage-enforcement.service..."
        $SUDO systemctl start grim-storage-enforcement.service
    fi
    
    success "Services restarted"
}

# ============================================================================
# ROLLBACK SUPPORT
# ============================================================================

show_rollback_info() {
    if [[ -f "/tmp/grim_backup_location" ]]; then
        local backup_dir=$(cat /tmp/grim_backup_location)
        echo ""
        warning "If you encounter issues, you can rollback using:"
        echo -e "${YELLOW}  $SUDO rm -rf $GRIM_INSTALL_DIR${NC}"
        echo -e "${YELLOW}  $SUDO mv $backup_dir $GRIM_INSTALL_DIR${NC}"
        echo -e "${YELLOW}  $SUDO systemctl restart grim.service${NC}"
        echo ""
        rm -f /tmp/grim_backup_location
    fi
} 

# ============================================================================
# INSTALLATION MODULE
# ============================================================================
# 🗡️ GRIM REAPER - INSTALLATION MODULE
# Core installation logic and file management

# ============================================================================
# UNIFIED SAFE INSTALLATION
# ============================================================================

install_grim() {
    local build_dir="$1"
    local is_update="${2:-false}"
    
    if [[ "$is_update" == "true" ]]; then
        log "Installing Grim Reaper update with data preservation..."
    else
        log "Installing Grim Reaper..."
    fi
    
    # Check if grim_throne.sh exists (required for CLI) - ALWAYS use the one from throne directory
    if [[ -f "$build_dir/throne/grim_throne.sh" ]]; then
        log "Found REAL grim_throne.sh in throne directory - this is the complete version with all commands"
        cp "$build_dir/throne/grim_throne.sh" "$build_dir/grim_throne.sh"
        chmod +x "$build_dir/grim_throne.sh"
    else
        # Fallback - check if it's already in the main directory
        if [[ ! -f "$build_dir/grim_throne.sh" ]]; then
            error "grim_throne.sh not found in build - this is required for the unified CLI"
        else
            warning "Using grim_throne.sh from main directory - this may not have all commands"
        fi
    fi
    
    # Create installation directory
    $SUDO mkdir -p "$GRIM_INSTALL_DIR"
    
    # For updates, use safe copying that preserves user data
    if [[ "$is_update" == "true" ]]; then
        log "Using safe copy mode - preserving existing user data directories..."
        
        # Create a list of directories/files to exclude during updates
        local exclude_patterns=(
            "db"
            "backups" 
            "logs"
            ".graveyard"
            "grim_venv"
            "*.user.*"
            "*.local.*"
            "*.custom.*"
            ".env"
            ".env.local"
            "user_data"
            "custom"
            "local"
        )
        
        # Build rsync exclude parameters
        local rsync_excludes=""
        for pattern in "${exclude_patterns[@]}"; do
            rsync_excludes="$rsync_excludes --exclude=$pattern"
        done
        
        # Use rsync for safe copying that respects excludes
        if command -v rsync >/dev/null 2>&1; then
            log "Using rsync for safe file copying..."
            if $SUDO rsync -av $rsync_excludes "$build_dir"/ "$GRIM_INSTALL_DIR/"; then
                # Handle new graveyard format - update backup directories and .rip structure
                local temp_dir_parent=$(dirname "$build_dir")
                local graveyard_target=$(dirname "$GRIM_INSTALL_DIR")
                
                # For new format, build_dir is "graveyard/reaper", so we need to go up one more level
                if [[ "$build_dir" == *"graveyard/reaper"* ]]; then
                    temp_dir_parent="."
                fi
                
                if [[ -d "$temp_dir_parent/graveyard" ]]; then
                    log "Updating backup directories and .rip structure from new graveyard format..."
                    
                    # Update .rip directory
                    if [[ -d "$temp_dir_parent/graveyard/.rip" ]]; then
                        log "Updating .rip directory structure..."
                        $SUDO mkdir -p "$graveyard_target/.rip"
                        $SUDO rsync -av "$temp_dir_parent/graveyard/.rip"/ "$graveyard_target/.rip/"
                    fi
                    
                    # Update backup directories (preserve existing backups)
                    if [[ -d "$temp_dir_parent/graveyard/auto_backups" ]]; then
                        log "Updating auto_backups directory..."
                        $SUDO mkdir -p "$graveyard_target/auto_backups"
                        $SUDO rsync -av "$temp_dir_parent/graveyard/auto_backups"/ "$graveyard_target/auto_backups/"
                    fi
                    
                    if [[ -d "$temp_dir_parent/graveyard/auto_backups_encrypted" ]]; then
                        log "Updating auto_backups_encrypted directory..."
                        $SUDO mkdir -p "$graveyard_target/auto_backups_encrypted"
                        $SUDO rsync -av "$temp_dir_parent/graveyard/auto_backups_encrypted"/ "$graveyard_target/auto_backups_encrypted/"
                    fi
                    
                    # Update backup log files
                    if [[ -f "$temp_dir_parent/graveyard/auto_backup.log" ]]; then
                        log "Updating auto_backup.log..."
                        $SUDO cp "$temp_dir_parent/graveyard/auto_backup.log" "$graveyard_target/"
                    fi
                    
                    # Set special permissions for backup directories (chmod 777 +x)
                    log "Setting special permissions for backup directories..."
                    local backup_dirs=("$graveyard_target/.rip" "$graveyard_target/auto_backups" "$graveyard_target/auto_backups_encrypted")
                    local permission_count=0
                    
                    for backup_dir in "${backup_dirs[@]}"; do
                        if [[ -d "$backup_dir" ]]; then
                            $SUDO chmod -R 777 "$backup_dir"
                            $SUDO find "$backup_dir" -type f -exec chmod +x {} \;
                            log "Set chmod 777 +x for: $backup_dir"
                            ((permission_count++))
                        fi
                    done
                    
                    if [[ $permission_count -ge 3 ]]; then
                        success "Set special permissions for $permission_count backup directories (chmod 777 +x)"
                    else
                        success "Set special permissions for $permission_count backup directories (chmod 777 +x)"
                    fi
                    
                    success "New graveyard structure with backup directories updated"
                fi
                success "Grim files updated safely (user data preserved)"
            else
                warning "rsync failed - falling back to manual safe copy"
                install_grim_manual_safe_copy "$build_dir"
            fi
        else
            log "rsync not available - using manual safe copy..."
            install_grim_manual_safe_copy "$build_dir"
        fi
    else
        # Fresh install - copy everything normally
        log "Fresh installation - copying all files..."
        $SUDO cp -r "$build_dir"/* "$GRIM_INSTALL_DIR/"
        
        # Handle new graveyard format - copy backup directories and .rip structure
        local temp_dir_parent=$(dirname "$build_dir")
        local graveyard_target=$(dirname "$GRIM_INSTALL_DIR")
        
        # For new format, build_dir is "graveyard/reaper", so we need to go up one more level
        if [[ "$build_dir" == *"graveyard/reaper"* ]]; then
            temp_dir_parent="."
        fi
        
        if [[ -d "$temp_dir_parent/graveyard" ]]; then
            log "Installing backup directories and .rip structure from new graveyard format..."
            
            # Copy .rip directory
            if [[ -d "$temp_dir_parent/graveyard/.rip" ]]; then
                log "Copying .rip directory structure..."
                $SUDO mkdir -p "$graveyard_target/.rip"
                $SUDO cp -r "$temp_dir_parent/graveyard/.rip"/* "$graveyard_target/.rip/"
            fi
            
            # Copy backup directories
            if [[ -d "$temp_dir_parent/graveyard/auto_backups" ]]; then
                log "Copying auto_backups directory..."
                $SUDO cp -r "$temp_dir_parent/graveyard/auto_backups" "$graveyard_target/"
            fi
            
            if [[ -d "$temp_dir_parent/graveyard/auto_backups_encrypted" ]]; then
                log "Copying auto_backups_encrypted directory..."
                $SUDO cp -r "$temp_dir_parent/graveyard/auto_backups_encrypted" "$graveyard_target/"
            fi
            
            # Copy any backup log files
            if [[ -f "$temp_dir_parent/graveyard/auto_backup.log" ]]; then
                log "Copying auto_backup.log..."
                $SUDO cp "$temp_dir_parent/graveyard/auto_backup.log" "$graveyard_target/"
            fi
            
            # Set special permissions for backup directories (chmod 777 +x)
            log "Setting special permissions for backup directories..."
            local backup_dirs=("$graveyard_target/.rip" "$graveyard_target/auto_backups" "$graveyard_target/auto_backups_encrypted")
            local permission_count=0
            
            for backup_dir in "${backup_dirs[@]}"; do
                if [[ -d "$backup_dir" ]]; then
                    $SUDO chmod -R 777 "$backup_dir"
                    $SUDO find "$backup_dir" -type f -exec chmod +x {} \;
                    log "Set chmod 777 +x for: $backup_dir"
                    ((permission_count++))
                fi
            done
            
            if [[ $permission_count -ge 3 ]]; then
                success "Set special permissions for $permission_count backup directories (chmod 777 +x)"
            else
                success "Set special permissions for $permission_count backup directories (chmod 777 +x)"
            fi
            
            success "New graveyard structure with backup directories installed"
        fi
        
        success "Grim Reaper installed to $GRIM_INSTALL_DIR"
    fi
    
    # Set permissions
    $SUDO chown -R root:root "$GRIM_INSTALL_DIR"
    $SUDO chmod -R 755 "$GRIM_INSTALL_DIR"
    $SUDO find "$GRIM_INSTALL_DIR" -name "*.sh" -exec chmod +x {} \;
    $SUDO find "$GRIM_INSTALL_DIR" -name "*.py" -exec chmod +x {} \;
    
    # Copy the actual commands documentation if available
    if [[ -f "$build_dir/throne/actual_commands.txt" ]]; then
        log "Copying commands documentation..."
        $SUDO cp "$build_dir/throne/actual_commands.txt" "$GRIM_INSTALL_DIR/commands.txt"
    fi
    
    # Install grim command
    log "Installing grim command..."
    $SUDO ln -sf "$GRIM_INSTALL_DIR/grim_throne.sh" /usr/local/bin/grim
    $SUDO chmod +x /usr/local/bin/grim
    
    if [[ "$is_update" == "true" ]]; then
        success "Grim Reaper updated safely (user data preserved)"
    else
        success "Grim Reaper installed to $GRIM_INSTALL_DIR"
    fi
}

# Manual safe copy helper function (only used for updates when rsync fails)
install_grim_manual_safe_copy() {
    local build_dir="$1"
    
    log "Performing manual safe copy (preserving user data)..."
    
    # Copy all files from build directory
    find "$build_dir" -maxdepth 1 -type f -exec $SUDO cp {} "$GRIM_INSTALL_DIR/" \;
    
    # Copy directories safely (excluding user data directories during updates)
    for item in "$build_dir"/*; do
        if [[ -d "$item" ]]; then
            local dirname=$(basename "$item")
            
            # Skip user data directories during updates only
            case "$dirname" in
                "db"|"backups"|"logs"|".graveyard"|"grim_venv"|"user_data"|"custom"|"local")
                    log "Skipping user data directory during update: $dirname"
                    ;;
                *)
                    log "Copying/updating program directory: $dirname"
                    $SUDO cp -r "$item" "$GRIM_INSTALL_DIR/"
                    ;;
            esac
        fi
    done
    
    # Handle new graveyard format backup directories in manual mode
    local temp_dir_parent=$(dirname "$build_dir")
    local graveyard_target=$(dirname "$GRIM_INSTALL_DIR")
    
    # For new format, build_dir is "graveyard/reaper", so we need to go up one more level
    if [[ "$build_dir" == *"graveyard/reaper"* ]]; then
        temp_dir_parent="."
    fi
    
    if [[ -d "$temp_dir_parent/graveyard" ]]; then
        log "Manual copy: Installing backup directories from new graveyard format..."
        
        # Copy .rip directory
        if [[ -d "$temp_dir_parent/graveyard/.rip" ]]; then
            log "Manual copy: .rip directory structure..."
            $SUDO mkdir -p "$graveyard_target/.rip"
            $SUDO cp -r "$temp_dir_parent/graveyard/.rip"/* "$graveyard_target/.rip/"
        fi
        
        # Copy backup directories
        if [[ -d "$temp_dir_parent/graveyard/auto_backups" ]]; then
            $SUDO cp -r "$temp_dir_parent/graveyard/auto_backups" "$graveyard_target/"
        fi
        
        if [[ -d "$temp_dir_parent/graveyard/auto_backups_encrypted" ]]; then
            $SUDO cp -r "$temp_dir_parent/graveyard/auto_backups_encrypted" "$graveyard_target/"
        fi
        
        # Copy backup log files
        if [[ -f "$temp_dir_parent/graveyard/auto_backup.log" ]]; then
            $SUDO cp "$temp_dir_parent/graveyard/auto_backup.log" "$graveyard_target/"
        fi
        
        # Set special permissions for backup directories (chmod 777 +x)
        log "Manual copy: Setting special permissions for backup directories..."
        local backup_dirs=("$graveyard_target/.rip" "$graveyard_target/auto_backups" "$graveyard_target/auto_backups_encrypted")
        local permission_count=0
        
        for backup_dir in "${backup_dirs[@]}"; do
            if [[ -d "$backup_dir" ]]; then
                $SUDO chmod -R 777 "$backup_dir"
                $SUDO find "$backup_dir" -type f -exec chmod +x {} \;
                log "Manual copy: Set chmod 777 +x for: $backup_dir"
                ((permission_count++))
            fi
        done
        
        if [[ $permission_count -ge 3 ]]; then
            success "Manual copy: Set special permissions for $permission_count backup directories (chmod 777 +x)"
        else
            success "Manual copy: Set special permissions for $permission_count backup directories (chmod 777 +x)"
        fi
    fi
    
    success "Manual safe copy completed"
}

# ============================================================================
# POST-INSTALLATION SETUP
# ============================================================================

run_installation_script() {
    log "Running Grim installation script..."
    
    mkdir -p "$GRIM_INSTALL_DIR"
    cd "$GRIM_INSTALL_DIR"
    
    # Skip running full installer when called from master installer
    # The full installer expects to be run from a build directory
    log "Skipping full installer - Grim Reaper is ready to use"
    log "Run 'grim health check' to verify installation"
}

# ============================================================================
# AUTO-BACKUP SETUP
# ============================================================================

setup_strategic_auto_backup() {
    log "Setting up strategic auto-backup system..."
    
    # Create graveyard directory if it doesn't exist
    mkdir -p "$GRIM_GRAVEYARD"
    
    # Check if strategic auto-backup installer exists
    if [[ -f "$GRIM_INSTALL_DIR/sh_grim/install_auto_backup_strategic.sh" ]]; then
        # Make sure it's executable
        chmod +x "$GRIM_INSTALL_DIR/sh_grim/install_auto_backup_strategic.sh"
        chmod +x "$GRIM_INSTALL_DIR/sh_grim/auto_backup_strategic.sh"
        
        # Install strategic auto-backup system
        if "$GRIM_INSTALL_DIR/sh_grim/install_auto_backup_strategic.sh" install; then
            success "Strategic auto-backup system installed successfully"
            log "Auto-backup logs: /var/log/grim-auto-backup.log"
        else
            warning "Strategic auto-backup installation failed - will create post-install script"
            create_post_install_auto_backup_script
        fi
    else
        # Create a post-install auto-backup setup script for later execution
        log "Creating post-install auto-backup setup script..."
        create_post_install_auto_backup_script
    fi
}

create_post_install_auto_backup_script() {
    cat > "$GRIM_GRAVEYARD/setup_auto_backup.sh" << 'EOF'
# Post-install strategic auto-backup setup script
# This runs after the main installation completes

GRIM_GRAVEYARD="${GRIM_GRAVEYARD:-/root/.graveyard}"
GRIM_INSTALL_DIR="${GRIM_INSTALL_DIR:-/root/.graveyard/reaper}"

echo "Setting up strategic auto-backup system..."

if [[ -f "$GRIM_INSTALL_DIR/sh_grim/install_auto_backup_strategic.sh" ]]; then
    chmod +x "$GRIM_INSTALL_DIR/sh_grim/install_auto_backup_strategic.sh"
    chmod +x "$GRIM_INSTALL_DIR/sh_grim/auto_backup_strategic.sh"
    
    # Install strategic auto-backup system
    if "$GRIM_INSTALL_DIR/sh_grim/install_auto_backup_strategic.sh" install; then
        echo "✅ Strategic auto-backup system installed successfully"
        echo "📁 Backup location: /root/.graveyard/.rip/auto-backups/"
        echo "📋 Use 'grim auto-backup help' for commands"
    else
        echo "❌ Strategic auto-backup installation failed"
    fi
else
    echo "❌ Strategic auto-backup installer not found"
fi
EOF
    
    chmod +x "$GRIM_GRAVEYARD/setup_auto_backup.sh"
    success "Post-install auto-backup setup script created"
}

# ============================================================================
# ERROR TRACKING AND DATABASE
# ============================================================================

setup_error_tracking() {
    log "Setting up error tracking and local database..."
    
    mkdir -p "$GRIM_INSTALL_DIR"
    cd "$GRIM_INSTALL_DIR"
    
    # Create local SQLite database directory
    mkdir -p db
    
    # Initialize local SQLite database
    sqlite3 db/grim.db << 'EOF'
CREATE TABLE IF NOT EXISTS error_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    error_type TEXT NOT NULL,
    error_message TEXT NOT NULL,
    error_details TEXT,
    severity TEXT DEFAULT 'medium',
    hostname TEXT,
    user TEXT,
    resolved BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS install_analytics (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    install_type TEXT NOT NULL,
    success BOOLEAN NOT NULL,
    details TEXT,
    hostname TEXT,
    user TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS health_reports (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    health_status TEXT NOT NULL,
    details TEXT,
    hostname TEXT,
    user TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS system_info (
    key TEXT PRIMARY KEY,
    value TEXT,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

INSERT OR REPLACE INTO system_info (key, value) VALUES 
    ('installation_date', datetime('now')),
    ('version', '1.0.17'),
    ('status', 'installed'),
    ('install_id', '$(uuidgen 2>/dev/null || echo "$(date +%s)-$(hostname)-$$")'),
    ('api_key', '$(openssl rand -hex 32 2>/dev/null || echo "$(date +%s)-$(hostname)-$$-key")');
EOF
    
    success "Error tracking and local database setup complete"
} 

# ============================================================================
# ENVIRONMENT MODULE
# ============================================================================
# 🗡️ GRIM REAPER - ENVIRONMENT MODULE
# Environment setup, virtual environments, and dependency management

# ============================================================================
# ENVIRONMENT SETUP
# ============================================================================

setup_environment() {
    log "Setting up environment..."
    
    # Create required directories
    $SUDO mkdir -p "$GRIM_INSTALL_DIR"/{logs,db,backups,tmp,builds}
    $SUDO chown -R root:root "$GRIM_INSTALL_DIR"
    
    # Create graveyard directory
    $SUDO mkdir -p "$GRIM_GRAVEYARD"
    $SUDO chown -R root:root "$GRIM_GRAVEYARD"
    
    # Setup .scythe directory structure
    log "Setting up .scythe directory structure..."
    if [[ -f "$GRIM_INSTALL_DIR/scripts/setup_scythe_dirs.sh" ]]; then
        # Use the universal setup script
        if [[ -n "$SUDO" ]]; then
            "$GRIM_INSTALL_DIR/scripts/setup_scythe_dirs.sh" setup "$GRIM_INSTALL_DIR" yes
        else
            "$GRIM_INSTALL_DIR/scripts/setup_scythe_dirs.sh" setup "$GRIM_INSTALL_DIR" no
        fi
    else 
        # Fallback: create basic structure manually
        warning "Universal setup script not found - creating basic .scythe structure"
        $SUDO mkdir -p "$GRIM_INSTALL_DIR/.graveyard/.rip/.scythe"/{config,db,logs,run,integrations}
        $SUDO chown -R root:root "$GRIM_INSTALL_DIR/.graveyard" 2>/dev/null || true
        $SUDO chmod -R 755 "$GRIM_INSTALL_DIR/.graveyard" 2>/dev/null || true
    fi
    
    # Set up environment variables
    setup_environment_variables
    
    # Setup Python virtual environment
    setup_python_environment
    
    success "Environment configured"
}

# ============================================================================
# ENVIRONMENT VARIABLES
# ============================================================================

setup_environment_variables() {
    log "Setting up environment variables..."
    
    local bashrc_file profile_file
    if [[ "$GRIM_INSTALL_DIR" == "/root/.graveyard/reaper" ]]; then
        bashrc_file="/root/.bashrc"
        profile_file="/root/.profile"
    else
        bashrc_file="$HOME/.bashrc"
        profile_file="$HOME/.profile"
    fi
    
    # Add GRIM_ROOT environment variable
    if ! grep -q "GRIM_ROOT" "$bashrc_file" 2>/dev/null; then
        echo "export GRIM_ROOT=\"$GRIM_INSTALL_DIR\"" >> "$bashrc_file"
        log "Added GRIM_ROOT to $bashrc_file"
    fi
    
    if [[ -f "$profile_file" ]] && ! grep -q "GRIM_ROOT" "$profile_file" 2>/dev/null; then
        echo "export GRIM_ROOT=\"$GRIM_INSTALL_DIR\"" >> "$profile_file"
        log "Added GRIM_ROOT to $profile_file"
    fi
    
    # Set up PATH in bashrc
    if ! grep -q "$GRIM_INSTALL_DIR" "$bashrc_file" 2>/dev/null; then
        echo "export PATH=\"$GRIM_INSTALL_DIR/sh_grim:\$PATH\"" >> "$bashrc_file"
        log "Added PATH to $bashrc_file"
    fi
    
    # Export for current session
    export GRIM_ROOT="$GRIM_INSTALL_DIR"
    
    success "Environment variables configured"
}

# ============================================================================
# PYTHON VIRTUAL ENVIRONMENT
# ============================================================================

setup_python_environment() {
    log "Setting up Python virtual environment..."
    
    if ! command -v python3 >/dev/null 2>&1; then
        warning "Python3 not available - skipping virtual environment setup"
        return 1
    fi
    
    mkdir -p "$GRIM_INSTALL_DIR"
    cd "$GRIM_INSTALL_DIR"
    
    # Check if python3-venv is available
    if ! python3 -c "import venv" 2>/dev/null; then
        log "Installing python3-venv package..."
        install_package "python3-venv" || warning "Could not install python3-venv"
    fi
    
    # Create virtual environment
    log "Creating Python virtual environment..."
    local venv_created=false
    
    # Try standard venv first
    if python3 -c "import venv" 2>/dev/null; then
        log "Using python3 -m venv..."
        if python3 -m venv grim_venv; then
            venv_created=true
            success "Virtual environment created with venv"
        else
            warning "venv creation failed"
        fi
    fi
    
    # Try virtualenv if venv failed
    if [[ "$venv_created" != "true" ]] && command -v virtualenv >/dev/null 2>&1; then
        log "Using virtualenv..."
        if virtualenv grim_venv; then
            venv_created=true
            success "Virtual environment created with virtualenv"
        else
            warning "virtualenv creation failed"
        fi
    fi
    
    # Manual fallback if both failed
    if [[ "$venv_created" != "true" ]]; then
        warning "Standard virtual environment creation failed - creating manual structure"
        create_manual_venv
        venv_created=true
    fi
    
    # Install Python dependencies
    if [[ "$venv_created" == "true" ]]; then
        install_python_dependencies
    fi
    
    success "Python environment setup completed"
}

create_manual_venv() {
    log "Creating manual virtual environment structure..."
    
    # Create virtual environment directory structure
    mkdir -p grim_venv/bin grim_venv/lib/python3.12/site-packages grim_venv/include
    
    # Create symlinks to system Python and pip
    ln -sf /usr/bin/python3 grim_venv/bin/python
    ln -sf /usr/bin/python3 grim_venv/bin/python3
    ln -sf /usr/bin/pip3 grim_venv/bin/pip
    
    # Create proper activation script
    cat > grim_venv/bin/activate << 'EOF'
export VIRTUAL_ENV="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
export PATH="$VIRTUAL_ENV/bin:$PATH"
export PS1="(grim_venv) ${PS1:-$ }"
unset PYTHONHOME

# Set up pip to install to the virtual environment
export PIP_TARGET="$VIRTUAL_ENV/lib/python3.12/site-packages"
export PIP_USER=no
EOF
    chmod +x grim_venv/bin/activate
    
    # Create deactivate function
    cat > grim_venv/bin/deactivate << 'EOF'
unset VIRTUAL_ENV
unset PIP_TARGET
unset PIP_USER
# Restore original PS1, fallback to default if not set
if [[ "$PS1" == "(grim_venv) "* ]]; then
    export PS1="${PS1#(grim_venv) }"
else
    export PS1="$ "
fi
EOF
    chmod +x grim_venv/bin/deactivate
    
    success "Manual virtual environment structure created"
}

install_python_dependencies() {
    log "Installing Python dependencies..."
    
    # Activate virtual environment
    if [[ -f "grim_venv/bin/activate" ]]; then
        source grim_venv/bin/activate 2>/dev/null || {
            # Fallback activation
            export VIRTUAL_ENV="$(pwd)/grim_venv"
            export PATH="$VIRTUAL_ENV/bin:$PATH"
            export PIP_TARGET="$VIRTUAL_ENV/lib/python3.12/site-packages"
            export PIP_USER=no
        }
    fi
    
    # Install dependencies from requirements.txt if available
    if [[ -f "py_grim/requirements.txt" ]]; then
        log "Installing dependencies from requirements.txt..."
        if pip install -r py_grim/requirements.txt; then
            success "Python dependencies installed from requirements.txt"
        else
            warning "Failed to install all dependencies from requirements.txt - trying core packages..."
            install_core_python_packages
        fi
    else
        warning "No requirements.txt found - installing common dependencies..."
        install_core_python_packages
    fi
    
    # Ensure critical packages are available
    ensure_critical_python_packages
    
    success "Python dependencies installation completed"
}

install_core_python_packages() {
    local core_packages=("fastapi" "uvicorn" "pydantic" "sqlalchemy" "redis" "aiofiles" "PyYAML")
    
    for package in "${core_packages[@]}"; do
        log "Installing $package..."
        pip install "$package" || warning "Failed to install $package"
    done
}

ensure_critical_python_packages() {
    # Ensure tusktsk is available (critical for Grim configuration)
    log "Verifying tusktsk package availability..."
    if ! python3 -c "import tusktsk" 2>/dev/null; then
        log "Installing tusktsk package..."
        if pip install tusktsk; then
            success "tusktsk package installed successfully"
        else
            warning "Failed to install tusktsk - some configuration features may use fallback"
        fi
    else
        log "tusktsk package already available"
    fi
    
    # Verify FastAPI availability
    if python3 -c "import fastapi" 2>/dev/null; then
        success "FastAPI available - Python dependencies verified"
    else
        warning "FastAPI not available - some Python features may not work"
    fi
}

# ============================================================================
# VALIDATION
# ============================================================================

validate_installation() {
    log "Validating installation..."
    
    # Check if grim command works
    if command -v grim >/dev/null 2>&1; then
        success "grim command available"
    else
        error "grim command not found in PATH"
    fi
    
    # Check if grim_throne.sh exists
    if [[ -f "$GRIM_INSTALL_DIR/grim_throne.sh" ]]; then
        success "grim_throne.sh found"
    else
        error "grim_throne.sh not found"
    fi
    
    # Test grim health (if available)
    if grim health check >/dev/null 2>&1; then
        success "Grim health check passed"
    else
        warning "Grim health check failed - may need manual configuration"
    fi
    
    # Check version if possible
    if grim --version >/dev/null 2>&1; then
        local version=$(grim --version 2>/dev/null | head -1)
        success "Version: $version"
    fi
    
    success "Installation validated"
} 

