# Phase wrapper functions that call the real implementation
phase_summon() {
    detect_system
}

phase_detect() {
    # Check for existing installation and handle updates safely
    local is_update=false
    if detect_existing_installation; then
        is_update=true
        log "Existing installation detected: $EXISTING_GRIM_ROOT"
        
        # Update the installation directory to match existing installation
        GRIM_INSTALL_DIR="$EXISTING_GRIM_ROOT"
        GRIM_GRAVEYARD="$(dirname "$EXISTING_GRIM_ROOT")"
        
        export IS_UPDATE=true
        log "Update mode enabled"
    else
        log "No existing installation found - proceeding with fresh install"
        export IS_UPDATE=false
    fi
}

phase_preserve() {
    if [[ "${IS_UPDATE:-false}" == "true" ]]; then
        stop_services
        create_installation_backup "$EXISTING_GRIM_ROOT"
        preserve_user_data "$EXISTING_GRIM_ROOT"
        log "All critical data preserved - proceeding with safe update..."
    fi
}

phase_download() {
    local build_dir
    build_dir=$(download_grim 2>&1 | tail -1)
    echo "$build_dir" > /tmp/grim_build_dir
    log "Build directory: $build_dir"
}

phase_extract() {
    # Already handled in download phase for simplicity
    local build_dir=$(cat /tmp/grim_build_dir 2>/dev/null || echo "")
    if [[ -n "$build_dir" && -d "$build_dir" ]]; then
        log "Build directory verified: $build_dir"
    else
        error "Build directory not found"
    fi
}

