phase_verify() {
    if [[ "${IS_UPDATE:-false}" == "true" ]]; then
        log "Verifying data integrity after update..."
        # Simple verification
        local integrity_issues=0
        
        # Check that Grim program files are properly updated
        if [[ -f "$GRIM_INSTALL_DIR/grim_throne.sh" ]]; then
            if [[ -x "$GRIM_INSTALL_DIR/grim_throne.sh" ]]; then
                success "Main Grim executable verified and functional"
            else
                warning "Main Grim executable exists but is not executable - fixing..."
                $SUDO chmod +x "$GRIM_INSTALL_DIR/grim_throne.sh"
                if [[ -x "$GRIM_INSTALL_DIR/grim_throne.sh" ]]; then
                    success "Fixed: Made grim_throne.sh executable"
                else
                    warning "Failed to make grim_throne.sh executable"
                    ((integrity_issues++))
                fi
            fi
        else
            warning "Main Grim executable not found after update"
            ((integrity_issues++))
        fi
        
        if [[ $integrity_issues -eq 0 ]]; then
            success "Data integrity verification PASSED - all systems go!"
        else
            warning "Data integrity verification found $integrity_issues issues"
        fi
    fi
}

phase_cleanup() {
    # Clean up temporary files
    local build_dir=$(cat /tmp/grim_build_dir 2>/dev/null || echo "")
    if [[ -n "$build_dir" ]]; then
        local temp_dir=$(dirname "$build_dir")
        cleanup "$temp_dir"
    fi
    
    # Clean up other temp files
    rm -f /tmp/grim_build_dir /tmp/grim_backup_location 2>/dev/null || true
    
    success "Cleanup completed"
}

phase_seal() {
    log "Finalizing installation..."
    
    # Setup error tracking and local database
    setup_error_tracking
    
    success "Installation sealed and ready"
}

