    # Show completion
    showCompletion
    
    # Launch post-install optimization in background
    launch_post_install
    
    # Display final summary
    sleep 2
    display_summary
}

# ============================================================================
# NON-ANIMATED MAIN FLOW (FALLBACK)
# ============================================================================
main() {
    print_banner
    
    log "Starting Grim Reaper master installation with enhanced data protection..."
    
    detect_system
    
    # Check for post-install optimization availability
    check_post_install_availability
    
    # Check for existing installation and handle updates safely
    local is_update=false
    if detect_existing_installation; then
        is_update=true
        log "Existing installation detected: $EXISTING_GRIM_ROOT"
        
        # Update the installation directory to match existing installation
        GRIM_INSTALL_DIR="$EXISTING_GRIM_ROOT"
        GRIM_GRAVEYARD="$(dirname "$EXISTING_GRIM_ROOT")"
        
        # Enhanced safe update process
        stop_services
        create_installation_backup "$EXISTING_GRIM_ROOT"
        preserve_user_data "$EXISTING_GRIM_ROOT"
        
        log "✅ All critical data preserved - proceeding with safe update..."
    else
        log "No existing installation found - proceeding with fresh install"
    fi
    
    # Download and extract
    local build_dir
    build_dir=$(download_grim 2>&1 | tail -1)
    
    # Install dependencies
    install_all_dependencies
    
    # Use unified installation function
    install_grim "$build_dir" "$is_update"
    
    # Post-installation steps
    if [[ "$is_update" == "true" ]]; then
        restore_user_data "$GRIM_INSTALL_DIR"
        log "✅ Update-specific setup completed"
    fi
    
    setup_environment
    run_installation_script
    validate_installation
    
    # Setup strategic auto-backup system
    setup_strategic_auto_backup
    
    # Setup error tracking
    setup_error_tracking
    
    # Generate freemium token for new installations
    if [[ "$is_update" != "true" ]]; then
        generate_freemium_token
    fi
    
    # Restart services for updates
    if [[ "$is_update" == "true" ]]; then
        restart_services
        success "🎉 SAFE UPDATE COMPLETED SUCCESSFULLY! 🎉"
    else
        success "Grim installation completed successfully!"
    fi
    
    # Cleanup
    cleanup "$(dirname "$build_dir")"
    
    # Launch post-install optimization in background
    launch_post_install
    
    # Display summary
    display_summary
}

# Parse command line arguments
GRIM_NO_ANIMATION="${GRIM_NO_ANIMATION:-false}"

while [[ $# -gt 0 ]]; do
    case $1 in
        --version)
            GRIM_VERSION="$2"
            shift 2
            ;;
        --no-animation)
            GRIM_NO_ANIMATION=true
            shift
            ;;
        --help|-h)
            show_help
            exit 0
            ;;
        *)
            echo "Unknown option: $1" >&2
            show_help
            exit 1
            ;;
    esac
done

# ============================================================================
# TOKEN GENERATION
# ============================================================================

generate_freemium_token() {
    log "Generating freemium access token..."
    
    # Check if GRIMS_MOTHER is set in .bashrc
    if ! grep -q "GRIMS_MOTHER" ~/.bashrc 2>/dev/null; then
        warning "GRIMS_MOTHER not found in .bashrc - token generation may fail"
    fi
    
    # Get user email (try multiple methods)
    local user_email=""
    
    # Try git config first
    if command -v git >/dev/null 2>&1; then
        user_email=$(git config --global user.email 2>/dev/null || echo "")
    fi
    
    # Fallback to system user
    if [[ -z "$user_email" ]]; then
        local username=$(whoami 2>/dev/null || echo "user")
        local hostname=$(hostname 2>/dev/null || echo "localhost")
        user_email="${username}@${hostname}"
        warning "No git email found, using: $user_email"
    fi
    
    # Get user name
    local user_name=""
    if command -v git >/dev/null 2>&1; then
        user_name=$(git config --global user.name 2>/dev/null || echo "")
    fi
    
    if [[ -z "$user_name" ]]; then
        user_name=$(whoami 2>/dev/null || echo "Grim User")
    fi
    
    # Generate a freemium license key first (needed for token generation)
    local license_key="GRIM-FREE-$(openssl rand -hex 4 | tr '[:lower:]' '[:upper:]')-$(openssl rand -hex 4 | tr '[:lower:]' '[:upper:]')"
    
    log "Creating freemium license: $license_key"
    log "User: $user_name <$user_email>"
    
    # Determine the correct API endpoint
    # Try grim.so first (where endpoints are implemented), then fallback to rip.grim.so
    local api_endpoints=(
        "https://grim.so/scythe/generate/freemium"
        "https://rip.grim.so/scythe/generate/freemium"
        "http://localhost:4746/scythe/generate/freemium"
    )
    
    local token_generated=false
    local bearer_token=""
    
    for endpoint in "${api_endpoints[@]}"; do
        log "Trying endpoint: $endpoint"
        
        # Create the payload
        local payload=$(cat <<EOF
{
    "email": "$user_email",
    "name": "$user_name", 
    "license_key": "$license_key"
}
EOF
)
        
        # Try to generate token
        local response
        if response=$(curl -s -X POST "$endpoint" \
            -H "Content-Type: application/json" \
            -d "$payload" \
            --connect-timeout 10 \
            --max-time 30 2>/dev/null); then
            
            # Check if response contains success
            if echo "$response" | grep -q '"success": true'; then
                bearer_token=$(echo "$response" | grep -o '"bearer_token": *"[^"]*"' | cut -d'"' -f4)
                
                if [[ -n "$bearer_token" ]]; then
                    success "✅ Freemium token generated successfully!"
                    log "Endpoint used: $endpoint"
                    token_generated=true
                    break
                fi
            else
                warning "Token generation failed at $endpoint: $response"
            fi
        else
            warning "Failed to connect to $endpoint"
        fi
    done
    
    if [[ "$token_generated" == "true" && -n "$bearer_token" ]]; then
        # Save token to user's home directory
        local token_file="$HOME/.grim/token"
        mkdir -p "$HOME/.grim"
        echo "$bearer_token" > "$token_file"
        chmod 600 "$token_file"
        
        # Also save license key
        echo "$license_key" > "$HOME/.grim/license"
        chmod 600 "$HOME/.grim/license"
        
        # Add to .bashrc if not already there
        if ! grep -q "GRIM_TOKEN" ~/.bashrc 2>/dev/null; then
            echo "" >> ~/.bashrc
            echo "# Grim Reaper Configuration" >> ~/.bashrc
            echo "export GRIM_TOKEN=\"$bearer_token\"" >> ~/.bashrc
            echo "export GRIM_LICENSE=\"$license_key\"" >> ~/.bashrc
            success "Added GRIM_TOKEN and GRIM_LICENSE to ~/.bashrc"
        fi
        
        # Set for current session
        export GRIM_TOKEN="$bearer_token"
        export GRIM_LICENSE="$license_key"
        
        success "🎉 Freemium access configured!"
        info "Token saved to: $token_file"
        info "License saved to: $HOME/.grim/license"
        info "You now have access to /hell storage endpoints (FREE tier)"
        
        # Test the token
        test_freemium_token "$bearer_token"
        
    else
        warning "❌ Failed to generate freemium token"
        warning "You can manually generate one later with:"
        warning "curl -X POST https://rip.grim.so/scythe/generate/freemium \\"
        warning "  -H 'Content-Type: application/json' \\"
        warning "  -d '{\"email\":\"$user_email\",\"name\":\"$user_name\",\"license_key\":\"$license_key\"}'"
    fi
}

test_freemium_token() {
    local token="$1"
    
    log "Testing freemium token..."
    
    local test_endpoints=(
        "https://grim.so/scythe/validate"
        "https://rip.grim.so/scythe/validate"
        "http://localhost:4746/scythe/validate"
    )
    
    for endpoint in "${test_endpoints[@]}"; do
        local test_payload=$(cat <<EOF
{
    "token": "$token"
}
EOF
)
        
        local response
        if response=$(curl -s -X POST "$endpoint" \
            -H "Content-Type: application/json" \
            -H "Authorization: Bearer $token" \
            -d "$test_payload" \
            --connect-timeout 5 \
            --max-time 15 2>/dev/null); then
            
            if echo "$response" | grep -q '"valid": true'; then
                success "✅ Token validation successful at $endpoint"
                local tier=$(echo "$response" | grep -o '"tier": *"[^"]*"' | cut -d'"' -f4)
                info "Your tier: ${tier:-FREE}"
                return 0
            fi
        fi
    done
    
    warning "Token validation failed - but token was saved for later use"
    return 1
}

# ============================================================================
# MAIN EXECUTION
# ============================================================================

# Run installation (animated or fallback)
if [[ "${BASH_SOURCE[0]:-}" == "$0" ]] || [[ -z "${BASH_SOURCE[0]:-}" ]]; then
    # Animations are the default behavior - only disable if explicitly requested
    if [[ "${GRIM_NO_ANIMATION:-}" == "true" ]]; then
        # Only run non-animated if explicitly disabled
        main "$@"
    else
        # Default to animated version (the main user experience)
        runInstallation "$@"
    fi
fi